import 'dart:ui';import 'package:flutter/material.dart';import 'package:flutter/services.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import '../../../Config/Routes/route_name.dart';import '../../../main.dart';import 'loading_splash.dart';import 'background_painter.dart';import 'build_main_details_splash.dart';class SplashBody extends StatefulWidget {  const SplashBody({super.key});  @override  State<SplashBody> createState() => _SplashBodyState();}class _SplashBodyState extends State<SplashBody> {  double logoOpacity = 0.0;  double textOpacity = 0.0;  double loadingOpacity = 0.0;  @override  void initState() {    super.initState();    SystemChrome.setEnabledSystemUIMode(SystemUiMode.edgeToEdge);    _startAnimations();  }  void _startAnimations() async {    await Future.delayed(Duration(milliseconds: 300));    setState(() => logoOpacity = 1.0);    await Future.delayed(Duration(milliseconds: 300));    setState(() => textOpacity = 1.0);    await Future.delayed(Duration(milliseconds: 300));    setState(() => loadingOpacity = 1.0);    await Future.delayed(Duration(seconds: 2));    _navigateToNextScreen();  }  void _navigateToNextScreen() async {    await kNavigationService.clearAndNavigateTo(AppRoutes.boarding);  }  @override  void dispose() {    SystemChrome.setEnabledSystemUIMode(SystemUiMode.immersiveSticky);    super.dispose();  }  @override  Widget build(BuildContext context) {    return Scaffold(      body: Stack(        children: [          Container(            decoration: BoxDecoration(              gradient: LinearGradient(                begin: Alignment.centerLeft,                end: Alignment.centerRight,                colors: [                  Color(0xFF0E0F10),                  Color(0xFF222426),                  Color(0xFF151617),                  Color(0xFF1C1D1E),                  Color(0xFF44474B),                  Color(0xFF292B2D),                  Color(0xFF303236),                  Color(0xFF1C1D1E),                  Color(0xFF44474B),                  Color(0xFF292B2D),                  Color(0xFF303236),                ],                tileMode: TileMode.repeated,              ),            ),          ),          Positioned.fill(            child: BackdropFilter(              filter: ImageFilter.blur(sigmaX: 10, sigmaY: 10),              blendMode: BlendMode.darken,              child: Container(                color: Colors.black.withAlpha(0x40),              ),            ),          ),          Positioned.fill(            child: CustomPaint(              painter: BackgroundPainter(),              size: Size.infinite,            ),          ),          Positioned(              right: 0,              left: 0,              top: 188.5.h,              child: AnimatedOpacity(                duration: Duration(milliseconds: 500),                opacity: logoOpacity,                child: LogoAndText(),              )),          Positioned(            right: 0,            left: 0,            bottom: 148.h,            child: AnimatedOpacity(              duration: Duration(milliseconds: 500),              opacity: loadingOpacity,              child: Loading(),            ),          ),        ],      ),    );  }}